local verifiedSpellDescriptions = {
    [24352] = { en = "Your next melee or ranged attack within $d will Root the target for $1300493d. The duration of this effect is doubled if the target was moving. Only works against Beasts.", description = "Il tuo prossimo attacco in mischia o a distanza entro $d immobilizza il bersaglio per $1300493d. L'effetto dura il doppio se il bersaglio era in movimento. Funziona solo sulle Bestie." },
    [24353] = { en = "Reduces the Mana cost of your next Revive Pet cast within $d by $s1%.", description = "Riduce il costo in mana del prossimo lancio di Rianima Famiglio entro $d del $s1%." },
    [24354] = { en = "Heal your target for $s1. Usable while Silenced.", description = "Cura il bersaglio di $s1. Utilizzabile anche se silenziati." },
    [24363] = { en = "Regenerate $s1 mana per 5 sec for $d.", description = "Rigenera $s1 mana ogni 5 sec. per $d." },
    [24364] = { en = "Makes you immune to Stun and Movement Impairing effects for the next $d.  Also removes existing Stun and Movement Impairing effects.", description = "Ti rende immune agli effetti di stordimento e limitazione del movimento per $d. Rimuove anche gli effetti di stordimento e limitazione del movimento già presenti." },
    [24389] = { en = "Refreshes the cooldown of Fire Ward and causes Fire damage absorbed by it to increase the damage of your next Fire Blast cast within $d by $s2% of the damage absorbed.", description = "Azzera il tempo di recupero di Barriera del Fuoco e fa sì che i danni da Fuoco assorbiti aumentino i danni della tua prossima Esplosione di Fuoco entro $d di una quantità pari al $s2% dei danni assorbiti." },
    [24416] = { en = "Allows Aspect of the Beast and $s1% of the effect of Aspect of the Monkey to be shared with the Hunter's party.", description = "Permette di condividere con il gruppo del cacciatore l'Aspetto della Bestia e il $s1% dell'effetto dell'Aspetto della Scimmia." },
    [24451] = { en = "Puts your pet in stealth mode, but slows its movement to $24450s2% of normal. The first attack from stealth receives a $24450s3% bonus to damage.  Lasts until cancelled.", description = "Mette il tuo famiglio in modalità furtiva, ma riduce la sua velocità di movimento al $24450s2% del normale. Il primo attacco dalla furtività infligge il $24450s3% di danni aggiuntivi. Dura finché non viene annullato." },
    [24454] = { en = "Puts your pet in stealth mode, but slows its movement to $24452s2% of normal. The first attack from stealth receives a $24452s3% bonus to damage.  Lasts until cancelled.", description = "Mette il tuo famiglio in modalità furtiva, ma riduce la sua velocità di movimento al $24452s2% del normale. Il primo attacco dalla furtività infligge il $24452s3% di danni aggiuntivi. Dura finché non viene annullato." },
    [24455] = { en = "Puts your pet in stealth mode, but slows its movement to $24453s2% of normal. The first attack from stealth receives a $24453s3% bonus to damage.  Lasts until cancelled.", description = "Mette il tuo famiglio in modalità furtiva, ma riduce la sua velocità di movimento al $24453s2% del normale. Il primo attacco dalla furtività infligge il $24453s3% di danni aggiuntivi. Dura finché non viene annullato." },
    [24495] = { en = "Increases Arcane resistance by $24493s1.", description = "Aumenta la Resistenza all'Arcano di $24493s1." },
    [24498] = { en = "Increases the critical hit chance of spells by $s1% for $d.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi per $d." },
    [24532] = { en = "Instantly increases your energy by $s1.", description = "Aumenta istantaneamente la tua energia di $s1." },
    [24542] = { en = "Reduces the casting time of your Healing Touch spells by $s1%, and reduces the mana cost of your healing spells by $s2% for $d.", description = "Riduce del $s1% il tempo di lancio dei tuoi incantesimi Tocco Curativo e del $s2% il costo in mana degli incantesimi di cura per $d." },
    [24543] = { en = "Increases the critical hit chance of your Destruction spells by $s1% for $d.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi di Distruzione per $d." },
    [24544] = { en = "Increases the critical hit chance of your Arcane spells by $s1%, and increases the critical hit damage of your Arcane spells by $s2% for $d.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi di Arcano e del $s2% i danni critici degli incantesimi di Arcano per $d." },
    [24546] = { en = "Reduces the casting time of your Greater Heal spells by $s1%, and reduces the mana cost of your healing spells by $s2% for $d.", description = "Riduce del $s1% il tempo di lancio degli incantesimi Cura Maggiore e del $s2% il costo in mana degli incantesimi di cura per $d." },
    [24574] = { en = "Increases your armor by 2000 and defense skill by 30 for $d. Every time you take melee or ranged damage, this bonus is reduced by 200 armor and 3 defense.", description = "Aumenta la tua armatura di 2000 e l'abilità Difesa di 30 per $d. Ogni volta che subisci danni in mischia o a distanza, il bonus si riduce di 200 armatura e 3 Difesa." },
    [24577] = { en = "Blasts a single enemy for $s1 damage and lowers the attack power of all enemies in melee range by $s2 for $d.", description = "Colpisce un singolo nemico infliggendo $s1 danni e riduce di $s2 la potenza d'attacco di tutti i nemici a portata di mischia per $d." },
    [24599] = { en = "Party members within $24597a1 yards receive an extra $24597s1 damage to their next Physical attack.  Lasts $24597d.", description = "I membri del gruppo entro $24597a1 metri infliggono $24597s1 danni aggiuntivi al loro prossimo attacco fisico. Dura $24597d." },
    [24607] = { en = "Party members within $24603a1 yards receive an extra $24603s1 damage to their next Physical attack.  Lasts $24603d.", description = "I membri del gruppo entro $24603a1 metri infliggono $24603s1 danni aggiuntivi al loro prossimo attacco fisico. Dura $24603d." },
    [24608] = { en = "Party members within $24605a1 yards receive an extra $24605s1 damage to their next Physical attack.  Lasts $24605d.", description = "I membri del gruppo entro $24605a1 metri infliggono $24605s1 danni aggiuntivi al loro prossimo attacco fisico. Dura $24605d." },
    [24609] = { en = "Party members within $24604a1 yards receive an extra $24604s1 damage to their next Physical attack.  Lasts $24604d.", description = "I membri del gruppo entro $24604a1 metri infliggono $24604s1 danni aggiuntivi al loro prossimo attacco fisico. Dura $24604d." },
    [24610] = { en = "Increases the chance to hit with spells by $s1% for $d.", description = "Aumenta del $s1% la probabilità di colpire con gli incantesimi per $d." },
    [24658] = { en = "Increases your spell damage by up to 204 and your healing by up to 408 for $d. Every time you cast a spell, the bonus is reduced by 17 spell damage and 34 healing.", description = "Aumenta fino a 204 i danni degli incantesimi e fino a 408 le cure per $d. Ogni volta che lanci un incantesimo, il bonus si riduce di 17 ai danni degli incantesimi e 34 alle cure." },
    [24705] = { en = "Increases health and mana regeneration by $s1%, and Stamina by $s2%.  Lasts $d.", description = "Aumenta del $s1% la rigenerazione di salute e mana e del $s2% la Tempra. Dura $d." },
    [24833] = { en = "Shatters the Holy Mightstone, increasing Attack Power by $s1 against Undead and increasing Holy damage from spells and effects by up to $s2 against Undead.  Lasts $d.", description = "Frantuma la Pietra del Potere Sacro, aumentando di $s1 la potenza d'attacco contro i Non Morti e fino a $s2 i danni sacri inflitti da incantesimi ed effetti contro i Non Morti. Dura $d." },
    [24853] = { en = "Gaining $s1 Mana every $t1 sec.", description = "Rigenera $s1 mana ogni $t1 sec." },
    [24854] = { en = "Summons a Mana Spring Totem for $d, restoring $24853s1 Mana every $24853t1 sec to party members within $24853a1 yards.", description = "Evoca un Totem Fonte di Mana per $d, che ripristina $24853s1 mana ogni $24853t1 sec. ai membri del gruppo entro $24853a1 metri." },
    [24858] = { en = "Transforms the Druid into Moonkin Form. While in this form, the armor contribution from items is increased by $24905s1%, Omen of Clarity gains $s5% increased chance to trigger, and all party members within $24907a1 yards have their critical strike chance increased by $24907s1%, exclusive with Leader of the Pack. The Moonkin cannot cast healing spells while shapeshifted.\r\n\r\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", description = "Trasforma il druido in Forma del Lunagufo. In questa forma, il contributo all'armatura degli oggetti aumenta del $24905s1%, Presagio di Lucidità ha una probabilità di attivazione maggiore del $s5% e la probabilità di colpo critico di tutti i membri del gruppo entro $24907a1 metri aumenta del $24907s1%; l'effetto non si cumula con Leader of the Pack. In forma di Moonkin non puoi lanciare incantesimi di cura.\r\n\r\nLa trasformazione libera chi la lancia dagli effetti di Polymorph e limitazione del movimento." },
    [24865] = { en = "Restores $s1 Mana. This effect is doubled in Wasteland and Haunted areas.", description = "Ripristina $s1 mana. L'effetto è doppio nelle aree Wasteland e Haunted." },
    [24939] = { en = "Summons $s1 $lMurky:Murky; to accompany the caster until dismissed.", description = "Evoca $s1 $lMurky:Murky; perché accompagni chi lancia l'incantesimo finché non viene congedato." },
    [24968] = { en = "Reduces the mana cost of your Healing Touch and Tranquility spells by $s1%.", description = "Riduce del $s1% il costo in mana degli incantesimi Tocco Curativo e Tranquillità." },
    [25026] = { en = "10 mana per second.\r\nAutomatically fires a shot at the nearest enemy tonk within $25032a1 yards every $t1 sec, dealing $25032s1 damage per shot.\r\n", description = "10 mana al secondo.\r\nSpara automaticamente contro il tonk nemico più vicino entro $25032a1 metri ogni $t1 sec., infliggendo $25032s1 danni per colpo.\r\n" },
    [25064] = { en = "Increases damage done by shadow spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni inflitti dagli incantesimi e dagli effetti d'Ombra." },
    [25065] = { en = "Increases damage done by fire spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni inflitti dagli incantesimi e dagli effetti di Fuoco." },
