    [25117] = { en = "While applied to target weapon it increases spell damage and healing by up to $25109s1. Lasts for 30 minutes.", description = "Quando applicato all'arma bersaglio, aumenta fino a $25109s1 i danni degli incantesimi e le cure. Dura 30 min." },
    [25119] = { en = "While applied to target weapon it increases spell damage and healing by up to $25110s1. Lasts for 30 minutes.", description = "Quando applicato all'arma bersaglio, aumenta fino a $25110s1 i danni degli incantesimi e le cure. Dura 30 min." },
    [25121] = { en = "While applied to target weapon it increases spell damage and healing by up to $25111s1. Lasts for 30 minutes.", description = "Quando applicato all'arma bersaglio, aumenta fino a $25111s1 i danni degli incantesimi e le cure. Dura 30 min." },
    [25199] = { en = "Transform yourself into a frog.  Lasts $d.", description = "Ti trasforma in una rana. Dura $d." },
    [25345] = { en = "Launches Arcane Missiles at the enemy, causing $25346s1 Arcane damage each second for $d.", description = "Scaglia Missili Arcani contro il nemico, infliggendo $25346s1 danni arcani ogni secondo per $d." },
    [25347] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $11356h% chance of poisoning the enemy for $25349o1 Nature damage over $25349d.  Stacks up to $25349u times on a single target.  $m3 charges.", description = "Ricopre un'arma di veleno per ${$m2/60} min.\r\nOgni colpo ha una probabilità del $11356h% di avvelenare il nemico, infliggendo $25349o1 danni da Natura in $25349d. Si accumula fino a $25349u volte sullo stesso bersaglio. $m3 cariche." },
    [25351] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy for $25349o1 Nature damage over $25349d.  Stacks up to $25349u times on a single target.  $m3 charges.", description = "Ricopre un'arma di veleno per ${$m1/60} min.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo $25349o1 danni da Natura in $25349d. Si accumula fino a $25349u volte sullo stesso bersaglio. $m3 cariche." },
    [25359] = { en = "Summons a Grace of Air Totem with $s1 health at the feet of the caster.  The totem increases the agility of party members within $25360a1 yards by $25360s1.  Lasts $d.", description = "Evoca ai piedi di chi lancia l'incantesimo un totem Grace of Air con $s1 salute. Il totem aumenta l'Agilità dei membri del gruppo entro $25360a1 metri di $25360s1. Dura $d." },
    [25361] = { en = "Summons a Strength of Earth Totem with $s1 health at the feet of the caster.  The totem increases the strength of party members within $25362a1 yards by $25362s1.  Lasts $d.", description = "Evoca ai piedi di chi lancia l'incantesimo un totem Forza della Terra con $s1 salute. Il totem aumenta la Forza dei membri del gruppo entro $25362a1 metri di $25362s1. Dura $d." },
    [25425] = { en = "Inflicts $s1 Nature damage to nearby enemies, reducing their attack speed by $s3% and slowing their movement to $s2% of normal for $d.", description = "Infligge $s1 danni da Natura ai nemici vicini, riducendone la velocità d'attacco del $s3% e la velocità di movimento al $s2% del normale per $d." },
    [25780] = { en = "Increases the threat generated by your Holy attacks by $s1%.  Lasts $d.", description = "Aumenta dell'$s1% la minaccia generata dai tuoi attacchi sacri. Dura $d." },
    [25805] = { en = "All stats reduced by 100.\r\n$s1 Shadow damage inflicted every $t1 sec.", description = "Tutte le statistiche sono ridotte di 100.\r\nInfligge $s1 danni da Ombra ogni $t1 sec." },
    [25848] = { en = "Target gets +10% melee crit.", description = "Il bersaglio ottiene +10% alla probabilità di critico in mischia." },
    [25890] = { en = "Gives all members of the raid or group that share the same class with the target the Greater Blessing of Light, increasing the effects of Holy Light spells used on the target by up to $s1 and the effect Flash of Light spells used on the target by up to $s2.  Lasts $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Conferisce a tutti i membri dell'incursione o del gruppo della stessa classe del bersaglio Benedizione Superiore della Luce, aumentando fino a $s1 l'effetto degli incantesimi Holy Light lanciati sul bersaglio e fino a $s2 quello degli incantesimi Flash of Light lanciati sul bersaglio. Dura $d. Ogni paladino può applicare una sola Benedizione a ciascun giocatore." },
    [25895] = { en = "Gives all members of the raid or group that share the same class with the target the Greater Blessing of Salvation, reducing the amount of all threat generated by $s1% for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Conferisce a tutti i membri dell'incursione o del gruppo della stessa classe del bersaglio Benedizione Superiore della Salvezza, riducendo del $s1% tutta la minaccia generata per $d. Ogni paladino può applicare una sola Benedizione a ciascun giocatore." },
    [25898] = { en = "Gives all members of the raid or group that share the same class with the target the Greater Blessing of Kings, increasing total stats by $s1% for $d.  Players may only have one Blessing on them per Paladin at any one time.", description = "Conferisce a tutti i membri dell'incursione o del gruppo della stessa classe del bersaglio Benedizione Superiore dei Re, aumentando dell'$s1% tutte le statistiche per $d. Ogni paladino può applicare una sola Benedizione a ciascun giocatore." },
    [25999] = { en = "Immobilize the target for $d.", description = "Immobilizza il bersaglio per $d." },
    [26019] = { en = "Permantly enchant boots to increase speed by $13889s1%.", description = "Incanta permanentemente gli stivali aumentando la velocità di movimento del $13889s1%." },
    [26020] = { en = "Permanently enchant a cloak to give +$13839s1 Herbalism", description = "Incanta permanentemente un mantello conferendo $13839s1 all'abilità Erbalismo." },
