    [26064] = { en = "Reduces all damage your pet takes by $s1% and increases the time between your pet's attacks by $s2%, but deals more damage with each attack. Lasts $d.", description = "Riduce del $s1% tutti i danni subiti dal tuo famiglio e aumenta del $s2% l'intervallo tra i suoi attacchi, ma aumenta i danni inflitti da ciascun attacco. Dura $d." },
    [26066] = { en = "Calls forth a Timbermaw Ancestor to fight at your side and heal you for $d.", description = "Evoca un Antenato dei Mordilegno che combatte al tuo fianco e ti cura per $d." },
    [26110] = { en = "Increase the Slow effect and damage of Thunder Clap by $s1%.", description = "Aumenta del $s1% l'effetto rallentante e i danni di Tuono." },
