    [26121] = { en = "Increases damage done by Nature spells and effects by up to $s1 for $d.", description = "Aumenta fino a $s1 i danni inflitti dagli incantesimi e dagli effetti di Natura per $d." },
    [26129] = { en = "Increases Spell Hit Chance by $s1% for $d. Stacks up to 4 times.", description = "Aumenta del $s1% la probabilità di colpire con gli incantesimi per $d. Si accumula fino a 4 volte." },
