    [26573] = { en = "Consecrates the land beneath the Paladin, doing ${$1280345m1*8} Holy damage over $d to enemies who enter the area The first $s3 enemies who enter the area will take an additional ${$1280345m2*8} damage over $d.", description = "Consacra il terreno sotto il paladino, infliggendo ${$1280345m1*8} danni sacri in $d ai nemici che entrano nell'area. I primi $s3 nemici che vi entrano subiscono inoltre ${$1280345m2*8} danni aggiuntivi in $d." },
