    [27680] = { en = "Increases the caster's movement speed by $s2% and the Physical damage it deals by $s1 for $d.", description = "Aumenta del $s2% la velocità di movimento di chi lancia l'incantesimo e di $s1 i danni fisici che infligge per $d." },
    [27683] = { en = "Power infuses all party and raid members, increasing their Shadow resistance by $s1 for $d.", description = "La potenza pervade tutti i membri del gruppo e dell'incursione, aumentando di $s1 la loro Resistenza all'Ombra per $d." },
    [27733] = { en = "Reduces the hit chance of Silence and Interrupt effects against you by $s1%.", description = "Riduce del $s1% la probabilità di essere colpito da effetti di Silenzio e interruzione." },
    [27753] = { en = "Place a frost trap that freezes the first enemy that approaches, preventing all action for up to $14309d.  Any damage caused will break the ice.  Trap will exist for $d.  Traps can only be placed when out of combat.  Only one trap can be active at a time.", description = "Piazza una trappola di gelo che congela il primo nemico che si avvicina, impedendogli di agire per un massimo di $14309d. Qualsiasi danno rompe il ghiaccio. La trappola resta attiva per $d. Può essere piazzata solo fuori dal combattimento e può esserci una sola trappola attiva alla volta." },
    [27774] = { en = "Chance on spell cast to increase your damage and healing by up to $27775s1 for $27775d.", description = "Quando lanci un incantesimo, hai una probabilità di aumentare fino a $27775s1 i danni e le cure per $27775d." },
    [27778] = { en = "When struck in combat has a $h% chance of shielding the wearer in a protective shield which will absorb $27779s1 damage. Can only occur once every $proccooldown sec.", description = "Quando vieni colpito in combattimento, hai una probabilità del $h% di essere protetto da uno scudo che assorbe $27779s1 danni. Può attivarsi solo una volta ogni $proccooldown sec." },
    [27780] = { en = "When struck in combat has a $h% chance of causing the attacker to flee in terror for $21330d. Can only occur once every $proccooldown sec.", description = "Quando vieni colpito in combattimento, hai una probabilità del $h% di far fuggire terrorizzato l'attaccante per $21330d. Può attivarsi solo una volta ogni $proccooldown sec." },
    [27783] = { en = "Generate ${$s1/10} Rage.", description = "Genera ${$s1/10} Rabbia." },
    [27784] = { en = "Restores $o1 energy over $d.", description = "Ripristina $o1 energia in $d." },
    [27787] = { en = "Chance on melee attack to restore $27788S1 Energy.", description = "Con gli attacchi in mischia, hai una probabilità di ripristinare $27788S1 energia." },
    [27788] = { en = "Restores $s1 Energy.", description = "Ripristina $s1 energia." },
    [27789] = { en = "Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing and Holy Nova spells by $s1%.", description = "Aumenta del $s1% la portata degli incantesimi Punizione e Fuoco Sacro e il raggio degli incantesimi Preghiera di Cura e Nova Sacra." },
    [27797] = { en = "Reduces the Mana cost of Riptide by $s1%.", description = "Riduce del $s1% il costo in mana di Riptide." },
    [27799] = { en = "Causes an explosion of holy light around the caster, causing $s1 Holy damage to all enemy targets within $a1 yards and healing all party members within $27803a1 yards for $27803s1. These effects cause no threat.\r\n\r\nEach time Holy Fire deals damage, you have a 5% chance for your next Holy Nova to cost no Mana.\r\n", description = "Provoca un'esplosione di luce sacra intorno a chi lancia l'incantesimo, infliggendo $s1 danni sacri a tutti i nemici entro $a1 metri e curando tutti i membri del gruppo entro $27803a1 metri di $27803s1. Questi effetti non generano minaccia.\r\n\r\nOgni volta che Fuoco Sacro infligge danni, hai una probabilità del 5% di rendere gratuita la tua prossima Nova Sacra.\r\n" },
    [27800] = { en = "Causes an explosion of holy light around the caster, causing $s1 Holy damage to all enemy targets within $a1 yards and healing all party members within $27804a1 yards for $27804s1. These effects cause no threat.\r\n\r\nEach time Holy Fire deals damage, you have a 5% chance for your next Holy Nova to cost no Mana.\r\n", description = "Provoca un'esplosione di luce sacra intorno a chi lancia l'incantesimo, infliggendo $s1 danni sacri a tutti i nemici entro $a1 metri e curando tutti i membri del gruppo entro $27804a1 metri di $27804s1. Questi effetti non generano minaccia.\r\n\r\nOgni volta che Fuoco Sacro infligge danni, hai una probabilità del 5% di rendere gratuita la tua prossima Nova Sacra.\r\n" },
    [27801] = { en = "Causes an explosion of holy light around the caster, causing $s1 Holy damage to all enemy targets within $a1 yards and healing all party members within $27805a1 yards for $27805s1. These effects cause no threat.\r\n\r\nEach time Holy Fire deals damage, you have a 5% chance for your next Holy Nova to cost no Mana.\r\n", description = "Provoca un'esplosione di luce sacra intorno a chi lancia l'incantesimo, infliggendo $s1 danni sacri a tutti i nemici entro $a1 metri e curando tutti i membri del gruppo entro $27805a1 metri di $27805s1. Questi effetti non generano minaccia.\r\n\r\nOgni volta che Fuoco Sacro infligge danni, hai una probabilità del 5% di rendere gratuita la tua prossima Nova Sacra.\r\n" },
    [27811] = { en = "After being struck by a melee or ranged critical hit, or suffering more than $m2% of your maximum Health from a single attack, heal $s1% of the damage taken over $27813d. Refreshing this effect carries over any remaining healing.", description = "Dopo aver subito un colpo critico in mischia o a distanza, oppure un singolo attacco che ti infligge più del $m2% della tua salute massima, cura il $s1% dei danni subiti in $27813d. Rinnovare l'effetto trasferisce le cure rimanenti." },
    [27839] = { en = "Increases the percentage healed by your Vampiric Embrace by an additional $s1%.", description = "Aumenta di un ulteriore $s1% la percentuale di cure ricevute tramite Abbraccio Vampirico." },
    [27848] = { en = "Increases the duration of your Seal spells by ${$s1/1000} sec.", description = "Aumenta la durata dei tuoi incantesimi Sigillo di ${$s1/1000} sec." },
    [27850] = { en = "Reduces the Mana cost of Purify and Cleanse by $s1%.", description = "Riduce del $s1% il costo in mana di Purificazione e Purga." },
    [27851] = { en = "Reduces the energy cost of Claw, Rake, and Mangle by $s1.", description = "Riduce di $s1 il costo in energia di Artiglio, Rake e Mangle." },
    [27853] = { en = "Increases the initial healing of Regrowth by $s1% when cast on a target affected by your Rejuvenation.", description = "Aumenta del $s1% la cura iniziale di Ricrescita quando lanciata su un bersaglio affetto da Rinvigorimento." },
    [27855] = { en = "Increases healing done by Lesser Healing Wave by up to $s1.", description = "Aumenta fino a $s1 le cure inflitte da Ondata di Cura Inferiore." },
    [27859] = { en = "Increases the damage of your Shock spells by $s1%.", description = "Aumenta del $s1% i danni dei tuoi incantesimi Scossa." },
    [27860] = { en = "Deal $s1 Shadow damage.\r\nRestore $s2 mana.", description = "Infligge $s1 danni da Ombra.\r\nRipristina $s2 mana." },
    [27867] = { en = "When struck in combat has a $h% chance of freezing the attacker in place for $27868d. Can only occur once every $proccooldown sec.", description = "Quando vieni colpito in combattimento, hai una probabilità del $h% di congelare sul posto l'attaccante per $27868d. Può attivarsi solo una volta ogni $proccooldown sec." },
    [27870] = { en = "Creates a holy Lightwell near the priest.  Members of your raid or party can click the Lightwell to restore $27873o1 health over $27873d.  Being attacked cancels the effect.  Lightwell lasts for $d or 5 charges.", description = "Crea un Pozzo di Luce vicino al sacerdote. I membri del gruppo o dell'incursione possono cliccare il Pozzo di Luce per ripristinare $27873o1 salute in $27873d. Subire un attacco interrompe l'effetto. Il Pozzo di Luce dura $d o 5 cariche." },
    [27871] = { en = "Creates a holy Lightwell near the priest.  Members of your raid or party can click the Lightwell to restore $27874o1 health over $27874d.  Being attacked cancels the effect.  Lightwell lasts for $d or 5 charges.", description = "Crea un Pozzo di Luce vicino al sacerdote. I membri del gruppo o dell'incursione possono cliccare il Pozzo di Luce per ripristinare $27874o1 salute in $27874d. Subire un attacco interrompe l'effetto. Il Pozzo di Luce dura $d o 5 cariche." },
    [27993] = { en = "Inflicts normal damage plus $s1 to nearby enemies, reducing movement speed for $d.", description = "Infligge danni normali più $s1 ai nemici vicini e ne riduce la velocità di movimento per $d." },
    [28023] = { en = "Creates a Minor Healthstone that can be used to instantly restore $6262s1 health.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra della Salute Inferiore, utilizzabile per ripristinare istantaneamente $6262s1 salute.\r\n\r\nGli oggetti evocati scompaiono se si resta disconnessi per più di 15 minuti." },
    [28142] = { en = "Increases the spell critical chance of all party members within $a1 yards by $s1%.", description = "Aumenta la probabilità di colpo critico con gli incantesimi di tutti i membri del gruppo entro $a1 metri del $s1%." },
    [28143] = { en = "Increases damage and healing done by magical spells and effects of all party members within $a1 yards by up to $s1. ", description = "Aumenta i danni e le cure inflitti dagli incantesimi e dagli effetti magici a tutti i membri del gruppo entro $a1 metri, fino a $s1. " },
    [28144] = { en = "Increases healing done by magical spells and effects of all party members within $a1 yards by up to $s1. ", description = "Aumenta le cure inflitte dagli incantesimi e dagli effetti magici a tutti i membri del gruppo entro $a1 metri, fino a $s1. " },
    [28145] = { en = "Restores $s1 mana per 5 seconds to all party members within $a1 yards.", description = "Ripristina $s1 mana ogni 5 secondi a tutti i membri del gruppo entro $a1 metri." },
    [28169] = { en = "Injects a target with a mutagen that transforms them into an abomination after $d.", description = "Inietta nel bersaglio un mutageno che lo trasforma in un abominio dopo $d." },
    [28270] = { en = "Transforms the enemy into a cow, forcing it to wander around for up to $d.  While wandering, the cow cannot attack or cast spells but will regenerate very quickly.  Any damage will transform the target back into its normal form.  Only one target can be polymorphed at a time.  Only works on Beasts, Humanoids and Critters.", description = "Trasforma il nemico in una mucca e lo costringe a vagare per un massimo di $d. Durante l'effetto non può attaccare né lanciare incantesimi, ma rigenera salute molto rapidamente. Qualsiasi danno lo riporta alla forma normale. Si può trasformare un solo bersaglio alla volta. Funziona solo su Bestie, Umanoidi e Creature." },
    [28293] = { en = "Strikes nearby enemies with a lightning bolt that arcs to another nearby enemies. The spell affects up to $x1 targets, inflicting greater Nature damage to each successive target.", description = "Colpisce i nemici vicini con un fulmine che rimbalza su altri nemici nelle vicinanze. L'incantesimo può colpire fino a $x1 bersagli, infliggendo danni da Natura sempre maggiori a ciascun bersaglio successivo." },
    [28431] = { en = "Charges an enemy and causes poison damage to all within 10 yards of the target.", description = "Carica un nemico e infligge danni da Veleno a tutti i bersagli entro 10 m dal nemico colpito." },
    [28679] = { en = "Reduce enemy's health and mana by $s1%.", description = "Riduce di $s1% la salute e il mana del nemico." },
    [28682] = { en = "Increases critical strike chance from Fire damage spells by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi che infliggono danni da Fuoco." },
    [28732] = { en = "Sacrifices self, prevents and removes enrage. Silences nature spells for $d.  Reduces casting speed by $s1%.", description = "Si sacrifica, impedisce e rimuove l'effetto d'Ira. Silenzia gli incantesimi di Natura per $d. Riduce la velocità di lancio del $s1%." },
    [28756] = { en = "Increases Attack Power by $28758s1 for both you and your pet.", description = "Aumenta di $28758s1 la potenza d'attacco tua e del tuo famiglio." },
    [28758] = { en = "Increases Attack Power by $s1.", description = "Aumenta di $s1 la potenza d'attacco." },
    [28766] = { en = "Increases frost resistance by $s1.  Lasts $d.", description = "Aumenta la Resistenza al Gelo di $s1. Dura $d." },
    [28802] = { en = "Each spell you cast can trigger an Epiphany, increasing your mana regeneration by $28804s1 for $28804d.", description = "Ogni incantesimo lanciato può attivare un'Epifania, aumentando di $28804s1 la rigenerazione del mana per $28804d." },
    [28821] = { en = "Your Lightning Shield spell also grants you $28820s1 mana per 5 sec. while active.", description = "Finché è attivo, l'incantesimo Scudo di Fulmini ti conferisce anche $28820s1 mana ogni 5 sec." },
    [28842] = { en = "Improves your chance to hit with Sunder Armor, Heroic Strike, Revenge, and Shield Slam by $s1%.", description = "Aumenta del $s1% la probabilità di colpire con Fendi Armatura, Attacco Eroico, Vendetta e Scudo Devastante." },
    [28845] = { en = "When your health drops below 20%, for the next 5 seconds healing spells cast on you help you to Cheat Death, increasing healing done by up to $28846s1.", description = "Quando la tua salute scende sotto il 20%, per i successivi 5 secondi gli incantesimi di cura lanciati su di te ti aiutano a sfuggire alla morte, aumentando fino a $28846s1 le cure ricevute." },
    [28851] = { en = "Increases healing done by Flash of Light by up to $s1.", description = "Aumenta fino a $s1 le cure inflitte da Lampo di Luce." },
    [28853] = { en = "Causes Judgement to heal all nearby party members for $1302540s1.", description = "Fa sì che Giudizio curi tutti i membri del gruppo vicini di $1302540s1." },
    [28854] = { en = "Increases the damage of your Moonfire spell by up to $s1.", description = "Aumenta fino a $s1 i danni del tuo incantesimo Fuoco Lunare." },
    [28856] = { en = "Increases the maximum number of charges on your Water Shield by $s1.", description = "Aumenta di $s1 il numero massimo di cariche del tuo Scudo d'Acqua." },
    [28857] = { en = "Increases damage done by Chain Lightning and Lightning Bolt by up to $s1.", description = "Aumenta fino a $s1 i danni inflitti da Catena di Fulmini e Fulmine." },
    [28996] = { en = "Reduces damage taken from Fire, Frost, and Nature effects by $m1%.", description = "Riduce del $m1% i danni subiti dagli effetti di Fuoco, Gelo e Natura." },
    [28999] = { en = "Increases the range of your Lightning Bolt, Chain Lightning, Fire Nova, and Lava Burst spells by $m1 yards, and increases the range of your Flame Shock spell by $m2 yards.", description = "Aumenta di $m1 metri la portata degli incantesimi Fulmine, Catena di Fulmini, Nova di Fuoco e Eruzione di Lava e di $m2 metri quella dell'incantesimo Folgore del Fuoco." },
    [29005] = { en = "Increases the critical strike chance with your Shock, Lightning Bolt and Chain Lightning spells by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico dei tuoi incantesimi Scossa, Fulmine e Catena di Fulmini." },
    [29062] = { en = "Reduces the pushback suffered from damaging attacks while casting Lightning Bolt, Chain Lightning, and Lava Burst by $m1%.", description = "Riduce del $m1% l'interruzione del lancio causata dagli attacchi che infliggono danni mentre lanci Fulmine, Catena di Fulmini o Eruzione di Lava." },
    [29069] = { en = "Increases your damage dealt against undead by $s1%.", description = "Aumenta del $s1% i danni inflitti ai Non Morti." },
    [29074] = { en = "Your Fire and Frost critical strikes will refund $s1% of their base mana cost.", description = "I tuoi colpi critici di Fuoco e Gelo restituiscono il $s1% del loro costo base in mana." },
    [29107] = { en = "Scream fiercely, burning $s1 mana from enemies.", description = "Lancia un urlo feroce e brucia $s1 mana ai nemici." },
    [29112] = { en = "+$s1 Attack Power against Undead and Demons.  Allows the acquisition of Scourgestones on behalf of the Argent Dawn.", description = "+$s1 potenza d'attacco contro i Non Morti e i Demoni. Consente di raccogliere le Pietre del Flagello per conto dell'Alba d'Argento." },
    [29140] = { en = "Increases your Stamina and Strength by $m1%.", description = "Aumenta del $m1% la tua Tempra e la tua Forza." },
    [29159] = { en = "Improves your chance to get a critical strike with spells by ${$s1}.1% against undead.", description = "Aumenta di ${$s1}.1% la probabilità di infliggere colpi critici con gli incantesimi contro i Non Morti." },
    [29175] = { en = "Increases Fire Resistance by $s1.", description = "Aumenta di $s1 la Resistenza al Fuoco." },
    [29187] = { en = "Reduces the threat generated by your spells by $m1%.", description = "Riduce del $m1% la minaccia generata dai tuoi incantesimi." },
    [29206] = { en = "Increases the amount healed by your Healing Wave spell by $m1%.", description = "Aumenta del $m1% le cure inflitte dal tuo incantesimo Ondata di Cura." },
