    [29325] = { en = "Shoots acid bolts at an enemy, inflicting Nature damage, then additional damage every $t2 sec. for $d.", description = "Scaglia dardi acidi contro un nemico, infliggendo danni da Natura e poi danni aggiuntivi ogni $t2 sec. per $d." },
    [29438] = { en = "Improves your chance to hit with Frost and Fire spells by $s1%.", description = "Aumenta dell'$s1% la probabilità di colpire con gli incantesimi di Gelo e Fuoco." },
