    [29442] = { en = "Restores $29441s1% of total mana.", description = "Ripristina il $29441s1% del mana totale." },
    [29626] = { en = "Chance to strike your ranged target with a Shadowbolt for $29640s1 Shadow damage.", description = "Con gli attacchi a distanza, hai una probabilità di colpire il bersaglio con un Dardo d'Ombra che infligge $29640s1 danni da Ombra." },
    [29638] = { en = "Fires a Searing Arrow at the target for $s1 Fire damage.", description = "Scaglia una Freccia Rovente contro il bersaglio, infliggendo $s1 danni da Fuoco." },
    [29639] = { en = "Fires a Flaming Cannonball at your target for $s1 Fire damage.", description = "Scaglia una Palla di Cannone Fiammeggiante contro il bersaglio, infliggendo $s1 danni da Fuoco." },
    [29640] = { en = "Shadowbolt for $s1 Shadow damage.", description = "Dardo d'Ombra che infligge $s1 danni da Ombra." },
    [29641] = { en = "Fires a Shadow Shot at the target for $s1 Shadow damage.", description = "Scaglia un Tiro d'Ombra contro il bersaglio, infliggendo $s1 danni da Ombra." },
    [29644] = { en = "Strike your ranged target with a Fire Blast for $s1 Fire damage.", description = "Colpisce il bersaglio a distanza con un'Esplosione di Fuoco, infliggendo $s1 danni da Fuoco." },
    [29646] = { en = "Strike your ranged target with a Quill Shot for $s1 Nature damage.", description = "Colpisce il bersaglio a distanza con un Tiro di Piuma, infliggendo $s1 danni da Natura." },
    [29647] = { en = "Strike the target with a Flaming Shell for $s1 Fire damage.", description = "Colpisce il bersaglio con un Proiettile Fiammeggiante, infliggendo $s1 danni da Fuoco." },
    [29653] = { en = "Venom Shot the target for $s1 Nature damage.", description = "Colpisce il bersaglio con un Tiro Venefico, infliggendo $s1 danni da Natura." },
    [29655] = { en = "Strike your target with Keeper's Sting for $29655s1 Nature damage.", description = "Colpisce il bersaglio con la Puntura del Custode, infliggendo $29655s1 danni da Natura." },
    [30187] = { en = "Permanently enchant gloves to grant $13615s1 fishing skill.", description = "Incanta permanentemente i guanti conferendo $13615s1 all'abilità Pesca." },
    [30229] = { en = "Permanently enchant a 2H weapon to give $27836s1 Agility.", description = "Incanta permanentemente un'arma a due mani conferendo $27836s1 Agilità." },
    [30440] = { en = "Improves your chance to hit with Taunt and Challenging Shout by ${$s1}.1%.", description = "Aumenta di ${$s1}.1% la probabilità di colpire con Provocazione e Grido Sfidante." },
    [30812] = { en = "Increases your spell damage and healing by up to $m2% of your Intellect.", description = "Aumenta i danni e le cure dei tuoi incantesimi fino al $m2% del tuo Intelletto." },
    [30879] = { en = "Deals $s1 damage to all enemies in a $a1 yard radius from the caster.", description = "Infligge $s1 danni a tutti i nemici entro un raggio di $a1 m da chi lancia l'incantesimo." },
    [36936] = { en = "Returns your totems to the earth, giving you $s1% of the mana required to cast each totem destroyed by Totemic Recall.", description = "Riporta i tuoi totem alla terra, restituendoti il $s1% del mana usato per lanciare ciascun totem distrutto da Richiamo Totemico." },
    [335924] = { en = "Experience gains increased by $s1%.", description = "Aumenta del $s1% l'esperienza ottenuta." },
    [355363] = { en = "Increases critical chance of spells by $s1%, melee and ranged by $s3% and grants $s2 attack power. Lasts $d.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi, del $s3% quella degli attacchi in mischia e a distanza e conferisce $s2 potenza d'attacco. Dura $d." },
    [362859] = { en = "Quest experience increased by $s1%.", description = "Aumenta del $s1% l'esperienza ottenuta dalle missioni." },
    [363881] = { en = "Restores $o1 Health over $d. This healing is strongest at first. If finished, gain $1318070s1 Strength for $1318070d.", description = "Ripristina $o1 salute in $d. L'effetto di cura è più intenso all'inizio. Se viene completato, conferisce $1318070s1 Forza per $1318070d." },
    [366995] = { en = "Deals $s1 Arcane damage every $t1 sec.", description = "Infligge $s1 danni arcani ogni $t1 sec." },
    [367756] = { en = "Movement speed increased by $s1%.\r\nAttack speed increased $s2%.\r\nCasting time decreased by $s3%.", description = "Aumenta la velocità di movimento del $s1%.\r\nAumenta la velocità d'attacco del $s2%.\r\nRiduce il tempo di lancio degli incantesimi del $s3%." },
    [367792] = { en = "Movement speed increased by $s1%.\r\nMelee, ranged, and spell haste increased by $s2%.", description = "Aumenta la velocità di movimento del $s1%.\r\nAumenta del $s2% la rapidità degli attacchi in mischia e a distanza e degli incantesimi." },
    [367873] = { en = "Deals $s1 Shadow damage every $t1 sec.\r\nDecreases your chance to hit with spells and melee attacks by $s2%.", description = "Infligge $s1 danni da Ombra ogni $t1 sec.\r\nRiduce del $s2% la probabilità di colpire con gli incantesimi e gli attacchi in mischia." },
    [368388] = { en = "Increases the caster's attack speed by $s2% and all damage it deals by $s1 for $d.", description = "Aumenta del $s2% la velocità d'attacco di chi lancia l'incantesimo e di $s1 tutti i danni che infligge per $d." },
    [370289] = { en = "Turn $s2 lesser deathstones into a greater one.", description = "Trasforma $s2 Pietre della Morte Inferiori in una Pietra della Morte Superiore." },
    [370303] = { en = "Crush the orb, increasing the amount of lesser deathstones absorbed from Kel'Thuzad's minions by $s1% for $d.", description = "Schiaccia la sfera, aumentando del $s1% per $d la quantità di Pietre della Morte Inferiori assorbite dai seguaci di Kel'Thuzad." },
    [370308] = { en = "Subdues the will of an undead target within Naxxramas, causing them to become charmed for $d.", description = "Soggioga la volontà di un Non Morto bersaglio entro Naxxramas, ammaliandolo per $d." },
    [370337] = { en = "Inflicts $s1 Nature damage every $t1 sec while also increasing the chance for a melee, ranged, or spell critical by $s2% for $d.", description = "Infligge $s1 danni da Natura ogni $t1 sec. e aumenta del $s2% la probabilità di colpo critico in mischia, a distanza e con gli incantesimi per $d." },
    [370347] = { en = "Absorb the life force of those around you, increasing stamina by $370877s1 for each target hit. This effect stacks up to $370877u and lasts for $370877d.", description = "Assorbe l'energia vitale di chi ti circonda, aumentando la Tempra di $370877s1 per ogni bersaglio colpito. Si accumula fino a $370877u volte e dura $370877d." },
    [370391] = { en = "Prevents an attack that would otherwise kill you. Triggering this effect also grants you $370417d of damage immunity and shatters the phylactery.", description = "Impedisce un attacco che altrimenti ti ucciderebbe. Quando si attiva, ti rende immune ai danni per $370417d e distrugge il filatterio." },
}
for id, record in pairs(verifiedSpellDescriptions) do
    if ns.data.spellDescriptionOverrides[id] == nil then
        ns.data.spellDescriptionOverrides[id] = record
    end
